use std::env;
use std::fs;
use std::io::{self, Write, Read, BufRead};
use std::path::Path;
use std::process::ExitCode;

const VERSION: &str = "0.17.0";

const HELP_TEXT: &str = include_str!("help.txt");
const LIST_OPTIONS: &str = include_str!("list_options.txt");

// Template files
const T_HTML_CSS: &str = include_str!("templates/html.css");
const T_HTML_CSS_PRINT: &str = include_str!("templates/html.css.print");
const T_HTML_CSS_COLORS: &str = include_str!("templates/html.css.colors");
const T_HTML_JS: &str = include_str!("templates/html.js");
const T_HTML_HIGHLIGHT_JS: &str = include_str!("templates/html.highlight.js");
const T_HTML_HIGHLIGHT_CSS: &str = include_str!("templates/html.highlight.css");
const T_HTML_STANDALONE_TEMPLATE: &str = include_str!("templates/html.standalone.template");
const T_HTML_STANDALONE_JS: &str = include_str!("templates/html.standalone.js");
const T_HTML_DIR_TEMPLATE: &str = include_str!("templates/html.dir.template");
const T_EPUB_CSS: &str = include_str!("templates/epub.css");
const T_EPUB_CHAPTER_XHTML: &str = include_str!("templates/epub.chapter.xhtml");
const T_EPUB_TITLEPAGE_XHTML: &str = include_str!("templates/epub.titlepage.xhtml");
const T_TEX_TEMPLATE: &str = include_str!("templates/tex.template");

fn get_template(name: &str) -> Option<&'static str> {
    match name {
        "html.css" => Some(T_HTML_CSS),
        "html.css.print" => Some(T_HTML_CSS_PRINT),
        "html.css.colors" => Some(T_HTML_CSS_COLORS),
        "html.js" => Some(T_HTML_JS),
        "html.highlight.js" => Some(T_HTML_HIGHLIGHT_JS),
        "html.highlight.css" => Some(T_HTML_HIGHLIGHT_CSS),
        "html.standalone.template" => Some(T_HTML_STANDALONE_TEMPLATE),
        "html.standalone.js" => Some(T_HTML_STANDALONE_JS),
        "html.dir.template" => Some(T_HTML_DIR_TEMPLATE),
        "epub.css" => Some(T_EPUB_CSS),
        "epub.chapter.xhtml" => Some(T_EPUB_CHAPTER_XHTML),
        "epub.titlepage.xhtml" => Some(T_EPUB_TITLEPAGE_XHTML),
        "tex.template" => Some(T_TEX_TEMPLATE),
        _ => None,
    }
}

#[derive(Default, Clone)]
struct Args {
    force_emoji: bool,
    single: bool,
    no_fancy: bool,
    verbose: bool,
    autograph: bool,
    quiet: bool,
    create: Option<Vec<String>>,
    output: Option<String>,
    to: Option<String>,
    set: Option<Vec<String>>,
    list_options: bool,
    lang: Option<String>,
    print_template: Option<String>,
    stats: bool,
    help: bool,
    version: bool,
    book: Option<String>,
}

fn cli_error(msg: &str, usage: &str) -> ExitCode {
    let mut out = String::new();
    out.push_str(&format!("error: {}\n\n", msg));
    if !usage.is_empty() {
        out.push_str(&format!("{}\n\n", usage));
    }
    out.push_str("For more information, try '--help'.\n");
    eprint!("{}", out);
    ExitCode::from(2)
}

fn default_usage() -> &'static str {
    "Usage: executable [OPTIONS] [BOOK]"
}

fn unknown_arg(arg: &str) -> ExitCode {
    let mut msg = format!("unexpected argument '{}' found", arg);
    // Check for near-match suggestions
    let similar = find_similar(arg);
    let usage = if let Some(ref s) = similar {
        msg.push_str(&format!("\n\n  tip: a similar argument exists: '{}'", s));
        // Clap's usage changes based on which flag was near-matched
        format!("Usage: executable {} [BOOK]", s)
    } else {
        msg.push_str(&format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg));
        default_usage().to_string()
    };
    cli_error(&msg, &usage)
}

fn find_similar(arg: &str) -> Option<&'static str> {
    // Only suggest similar well-known flags
    let known = [
        "--force-emoji", "--single", "--no-fancy", "--verbose", "--autograph",
        "--quiet", "--create", "--output", "--to", "--set", "--list-options",
        "--lang", "--print-template", "--stats", "--help", "--version",
    ];
    let arg_l = arg.trim_start_matches('-');
    for k in &known {
        let k_l = k.trim_start_matches('-');
        if k_l.starts_with(arg_l) || arg_l.starts_with(k_l) {
            return Some(k);
        }
        // Simple edit distance
        if edit_distance(k_l, arg_l) <= 2 && arg_l.len() > 2 {
            return Some(k);
        }
    }
    None
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (n, m) = (a.len(), b.len());
    if n == 0 { return m; }
    if m == 0 { return n; }
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut curr = vec![0usize; m + 1];
    for i in 1..=n {
        curr[0] = i;
        for j in 1..=m {
            let cost = if a[i-1] == b[j-1] { 0 } else { 1 };
            curr[j] = (prev[j] + 1).min(curr[j-1] + 1).min(prev[j-1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[m]
}

fn parse_args(argv: Vec<String>) -> Result<Args, ExitCode> {
    let mut a = Args::default();
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 1usize; // skip program name
    let mut after_ddash = false;
    // Valid values for --to
    let valid_to = ["epub", "pdf", "html", "tex", "odt", "html.dir"];

    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if after_ddash {
            positionals.push(arg);
            continue;
        }
        if arg == "--" {
            after_ddash = true;
            continue;
        }
        // long options
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, val_opt) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(rest[pos+1..].to_string())),
                None => (rest, None),
            };
            match name {
                "help" => { a.help = true; }
                "version" => { a.version = true; }
                "force-emoji" => { a.force_emoji = true; }
                "single" => { a.single = true; }
                "no-fancy" => { a.no_fancy = true; }
                "verbose" => { a.verbose = true; }
                "autograph" => { a.autograph = true; }
                "quiet" => { a.quiet = true; }
                "list-options" => { a.list_options = true; }
                "stats" => { a.stats = true; }
                "lang" => {
                    if let Some(v) = val_opt { a.lang = Some(v); }
                    else if i < argv.len() { a.lang = Some(argv[i].clone()); i += 1; }
                    else {
                        return Err(cli_error(
                            "a value is required for '--lang <lang>' but none was supplied",
                            ""));
                    }
                }
                "output" => {
                    if let Some(v) = val_opt { a.output = Some(v); }
                    else if i < argv.len() { a.output = Some(argv[i].clone()); i += 1; }
                    else {
                        return Err(cli_error(
                            "a value is required for '--output <output>' but none was supplied",
                            ""));
                    }
                }
                "to" => {
                    let val = if let Some(v) = val_opt { Some(v) }
                    else if i < argv.len() { let v = argv[i].clone(); i += 1; Some(v) }
                    else { None };
                    match val {
                        Some(v) => {
                            if !valid_to.contains(&v.as_str()) {
                                let msg = format!(
                                    "invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]",
                                    v);
                                eprint!("error: {}\n\nFor more information, try '--help'.\n", msg);
                                return Err(ExitCode::from(2));
                            }
                            a.to = Some(v);
                        }
                        None => {
                            eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                            return Err(ExitCode::from(2));
                        }
                    }
                }
                "print-template" => {
                    if let Some(v) = val_opt { a.print_template = Some(v); }
                    else if i < argv.len() { a.print_template = Some(argv[i].clone()); i += 1; }
                    else {
                        return Err(cli_error(
                            "a value is required for '--print-template <print-template>' but none was supplied",
                            ""));
                    }
                }
                "create" => {
                    // consume one or more values up to next flag
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--create <files>...' but none was supplied",
                            ""));
                    }
                    a.create = Some(vals);
                }
                "set" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--set <set> <set>...' but none was supplied",
                            ""));
                    }
                    a.set = Some(vals);
                }
                _ => {
                    return Err(unknown_arg(&arg));
                }
            }
            continue;
        }
        // short option(s)
        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                match c {
                    'h' => a.help = true,
                    'V' => a.version = true,
                    'f' => a.force_emoji = true,
                    's' => a.single = true,
                    'n' => a.no_fancy = true,
                    'v' => a.verbose = true,
                    'a' => a.autograph = true,
                    'q' => a.quiet = true,
                    'l' => a.list_options = true,
                    'S' => a.stats = true,
                    'L' => {
                        // rest of chars is value, or next arg
                        if j < chars.len() {
                            a.lang = Some(chars[j..].iter().collect::<String>());
                            j = chars.len();
                        } else if i < argv.len() {
                            a.lang = Some(argv[i].clone());
                            i += 1;
                        } else {
                            return Err(cli_error(
                                "a value is required for '--lang <lang>' but none was supplied",
                                ""));
                        }
                    }
                    'o' => {
                        if j < chars.len() {
                            a.output = Some(chars[j..].iter().collect::<String>());
                            j = chars.len();
                        } else if i < argv.len() {
                            a.output = Some(argv[i].clone());
                            i += 1;
                        } else {
                            return Err(cli_error(
                                "a value is required for '--output <output>' but none was supplied",
                                ""));
                        }
                    }
                    't' => {
                        let val = if j < chars.len() {
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            Some(v)
                        } else if i < argv.len() {
                            let v = argv[i].clone();
                            i += 1;
                            Some(v)
                        } else { None };
                        match val {
                            Some(v) => {
                                if !valid_to.contains(&v.as_str()) {
                                    let msg = format!(
                                        "invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]",
                                        v);
                                    eprint!("error: {}\n\nFor more information, try '--help'.\n", msg);
                                    return Err(ExitCode::from(2));
                                }
                                a.to = Some(v);
                            }
                            None => {
                                eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                                return Err(ExitCode::from(2));
                            }
                        }
                    }
                    'c' => {
                        // consume rest of chars then up to next flag
                        let mut vals: Vec<String> = Vec::new();
                        if j < chars.len() {
                            vals.push(chars[j..].iter().collect::<String>());
                            j = chars.len();
                        }
                        while i < argv.len() && !argv[i].starts_with('-') {
                            vals.push(argv[i].clone());
                            i += 1;
                        }
                        if vals.is_empty() {
                            return Err(cli_error(
                                "a value is required for '--create <files>...' but none was supplied",
                                ""));
                        }
                        a.create = Some(vals);
                    }
                    _ => {
                        let bad = format!("-{}", c);
                        return Err(unknown_arg(&bad));
                    }
                }
            }
            continue;
        }
        // positional
        positionals.push(arg);
    }

    if positionals.len() > 1 {
        return Err(unknown_arg(&positionals[1]));
    }
    if let Some(p) = positionals.into_iter().next() {
        a.book = Some(p);
    }

    // Validate -o requires --to
    if a.output.is_some() && a.to.is_none() && a.create.is_none() {
        let msg = "the following required arguments were not provided:\n  --to <to>";
        let usage = "Usage: executable --to <to> --output <output> [BOOK]";
        return Err(cli_error(msg, usage));
    }
    // -o with -c requires --to too
    if a.output.is_some() && a.create.is_some() && a.to.is_none() {
        let msg = "the following required arguments were not provided:\n  --to <to>";
        let usage = "Usage: executable --to <to> --create <files>... --output <output> [BOOK]";
        return Err(cli_error(msg, usage));
    }

    Ok(a)
}

fn banner(a: &Args) -> String {
    if a.force_emoji {
        format!("🐦 CROWBOOK 📚 {}", VERSION)
    } else {
        format!("CROWBOOK {}", VERSION)
    }
}

fn error_prefix(a: &Args) -> &'static str {
    if a.force_emoji && !a.no_fancy {
        "💣 ERROR"
    } else {
        "ERROR"
    }
}

fn print_banner(a: &Args) {
    if !a.quiet {
        eprintln!("{}", banner(a));
    }
}

fn msg_must_pass_book(a: &Args) -> String {
    // Not translated to French
    format!("{} You must pass the name of a book configuration file.\nFor more information try --help.\n", error_prefix(a))
}

fn msg_not_found(a: &Args, path: &str) -> String {
    let french = a.lang.as_deref() == Some("fr");
    if french {
        format!("{} Impossible de trouver le fichier '{}' pour book", error_prefix(a), path)
    } else {
        format!("{} Could not find file '{}' for book", error_prefix(a), path)
    }
}

fn msg_not_found_chapter(a: &Args, path: &str) -> String {
    let french = a.lang.as_deref() == Some("fr");
    if french {
        format!("{} {}: Impossible de trouver le fichier '{}' pour book chapter", error_prefix(a), path, path)
    } else {
        format!("{} {}: Could not find file '{}' for book chapter", error_prefix(a), path, path)
    }
}

fn do_help(a: &Args) -> ExitCode {
    print!("{}", HELP_TEXT);
    let _ = io::stdout().flush();
    let _ = a;
    ExitCode::from(0)
}

fn do_version(_a: &Args) -> ExitCode {
