        }
    };
    if path != "-" && !Path::new(path).exists() {
        eprintln!("{}", msg_not_found(a, path));
        return ExitCode::from(0);
    }
    // Parse (best-effort)
    let book = if path == "-" {
        // Read stdin, we don't fully parse
        let mut s = String::new();
        let _ = io::stdin().read_to_string(&mut s);
        Book { chapters: Vec::new() }
    } else {
        match parse_book_file(path, a) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("{} {}", error_prefix(a), e);
                return ExitCode::from(0);
            }
        }
    };

    if a.stats {
        return do_stats(a, &book);
    }
    // Otherwise no rendering is performed.
    ExitCode::from(0)
}

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let args = match parse_args(argv) {
        Ok(a) => a,
        Err(code) => return code,
    };

    if args.help {
        return do_help(&args);
    }
    if args.version {
        return do_version(&args);
    }
    if args.list_options {
        return do_list_options(&args);
    }
    if let Some(t) = &args.print_template {
        return do_print_template(&args, t);
    }
    if let Some(files) = args.create.clone() {
        return do_create(&args, &files);
    }
    do_book(&args)
}

