fn cli_error(msg: &str, usage: &str) -> ExitCode {
    let mut out = String::new();
    out.push_str(&format!("error: {}\n\n", msg));
    if !usage.is_empty() {
        out.push_str(&format!("{}\n\n", usage));
    }
    out.push_str("For more information, try '--help'.\n");
    eprint!("{}", out);
    ExitCode::from(2)
}

fn default_usage() -> &'static str {
    "Usage: executable [OPTIONS] [BOOK]"
}

fn unknown_arg(arg: &str) -> ExitCode {
    let mut msg = format!("unexpected argument '{}' found", arg);
    // Check for near-match suggestions
    let similar = find_similar(arg);
    let usage = if let Some(ref s) = similar {
        msg.push_str(&format!("\n\n  tip: a similar argument exists: '{}'", s));
        // Clap's usage changes based on which flag was near-matched
        format!("Usage: executable {} [BOOK]", s)
    } else {
        msg.push_str(&format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg));
        default_usage().to_string()
    };
    cli_error(&msg, &usage)
}

fn find_similar(arg: &str) -> Option<&'static str> {
    // Only suggest similar well-known flags
    let known = [
        "--force-emoji", "--single", "--no-fancy", "--verbose", "--autograph",
        "--quiet", "--create", "--output", "--to", "--set", "--list-options",
        "--lang", "--print-template", "--stats", "--help", "--version",
    ];
    let arg_l = arg.trim_start_matches('-');
    for k in &known {
        let k_l = k.trim_start_matches('-');
        if k_l.starts_with(arg_l) || arg_l.starts_with(k_l) {
            return Some(k);
        }
        // Simple edit distance
        if edit_distance(k_l, arg_l) <= 2 && arg_l.len() > 2 {
            return Some(k);
        }
    }
    None
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (n, m) = (a.len(), b.len());
    if n == 0 { return m; }
    if m == 0 { return n; }
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut curr = vec![0usize; m + 1];
    for i in 1..=n {
        curr[0] = i;
        for j in 1..=m {
            let cost = if a[i-1] == b[j-1] { 0 } else { 1 };
            curr[j] = (prev[j] + 1).min(curr[j-1] + 1).min(prev[j-1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[m]
}

