        let v = argv[*i].clone();
        *i += 1;
        return Ok(v);
    }
    Err(cli_error(
        &format!("a value is required for '{}' but none was supplied", flag_usage),
        ""))
}

fn parse_args(argv: Vec<String>) -> Result<Args, ExitCode> {
    let mut a = Args::default();
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 1usize;
    let mut after_ddash = false;
    let valid_to = ["epub", "pdf", "html", "tex", "odt", "html.dir"];

    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if after_ddash {
            positionals.push(arg);
            continue;
        }
        if arg == "--" {
            after_ddash = true;
            continue;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, val_opt) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(rest[pos+1..].to_string())),
                None => (rest, None),
            };
            match name {
                "" => {
                    // "--" handled above; "--=" weird case
                    return Err(unknown_arg(&arg));
                }
                "help" => { a.help = true; }
                "version" => { a.version = true; }
                "force-emoji" => { a.force_emoji = true; }
                "single" => { a.single = true; }
                "no-fancy" => { a.no_fancy = true; }
                "verbose" => { a.verbose = true; }
                "autograph" => { a.autograph = true; }
                "quiet" => { a.quiet = true; }
                "list-options" => { a.list_options = true; }
                "stats" => { a.stats = true; }
                "lang" => {
                    a.lang = Some(take_value_for("--lang <lang>", &mut i, &argv, val_opt)?);
                }
                "output" => {
                    a.output = Some(take_value_for("--output <output>", &mut i, &argv, val_opt)?);
                }
                "to" => {
                    let v = match val_opt {
                        Some(v) => v,
                        None => {
                            if i < argv.len() {
                                let v = argv[i].clone();
                                i += 1;
                                v
                            } else {
                                eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                                return Err(ExitCode::from(2));
                            }
                        }
                    };
                    if !valid_to.contains(&v.as_str()) {
                        eprint!("error: invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n", v);
                        return Err(ExitCode::from(2));
                    }
                    a.to = Some(v);
                }
                "print-template" => {
                    a.print_template = Some(take_value_for("--print-template <print-template>", &mut i, &argv, val_opt)?);
                }
                "create" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--create <files>...' but none was supplied",
                            ""));
                    }
                    a.create = Some(vals);
                }
                "set" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--set <set> <set>...' but none was supplied",
                            ""));
                    }
                    a.set = Some(vals);
                }
                _ => {
                    return Err(unknown_arg(&arg));
                }
            }
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0usize;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                let take_short_value = |j: &mut usize, i: &mut usize, argv: &[String], flag: &str| -> Result<String, ExitCode> {
                    // skip optional '='
                    if *j < chars.len() && chars[*j] == '=' { *j += 1; }
                    if *j < chars.len() {
                        let v = chars[*j..].iter().collect::<String>();
                        *j = chars.len();
                        Ok(v)
                    } else if *i < argv.len() {
                        let v = argv[*i].clone();
                        *i += 1;
                        Ok(v)
                    } else {
                        Err(cli_error(&format!("a value is required for '{}' but none was supplied", flag), ""))
                    }
                };
                match c {
                    'h' => a.help = true,
                    'V' => a.version = true,
                    'f' => a.force_emoji = true,
                    's' => a.single = true,
                    'n' => a.no_fancy = true,
                    'v' => a.verbose = true,
                    'a' => a.autograph = true,
                    'q' => a.quiet = true,
                    'l' => a.list_options = true,
                    'S' => a.stats = true,
                    'L' => {
                        a.lang = Some(take_short_value(&mut j, &mut i, &argv, "--lang <lang>")?);
                    }
                    'o' => {
                        a.output = Some(take_short_value(&mut j, &mut i, &argv, "--output <output>")?);
                    }
                    't' => {
                        let v = if j < chars.len() && chars[j] == '=' {
                            j += 1;
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            v
                        } else if j < chars.len() {
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            v
                        } else if i < argv.len() {
                            let v = argv[i].clone();
                            i += 1;
                            v
                        } else {
                            eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                            return Err(ExitCode::from(2));
                        };
                        if !valid_to.contains(&v.as_str()) {
                            eprint!("error: invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n", v);
                            return Err(ExitCode::from(2));
                        }
                        a.to = Some(v);
                    }
                    'c' => {
                        let mut vals: Vec<String> = Vec::new();
                        if j < chars.len() && chars[j] == '=' { j += 1; }
                        if j < chars.len() {
                            vals.push(chars[j..].iter().collect::<String>());
                            j = chars.len();
                        }
                        while i < argv.len() && !argv[i].starts_with('-') {
                            vals.push(argv[i].clone());
                            i += 1;
                        }
                        if vals.is_empty() {
                            return Err(cli_error(
                                "a value is required for '--create <files>...' but none was supplied",
                                ""));
                        }
                        a.create = Some(vals);
                    }
                    _ => {
                        let bad = format!("-{}", c);
                        return Err(unknown_arg(&bad));
                    }
                }
            }
            continue;
        }
        positionals.push(arg);
    }

    if positionals.len() > 1 {
        return Err(unknown_arg(&positionals[1]));
    }
    if let Some(p) = positionals.into_iter().next() {
        a.book = Some(p);
    }

    if a.output.is_some() && a.to.is_none() {
        let msg = "the following required arguments were not provided:\n  --to <to>";
        let usage = if a.create.is_some() {
            "Usage: executable --to <to> --create <files>... --output <output> [BOOK]"
        } else {
            "Usage: executable --to <to> --output <output> [BOOK]"
        };
        return Err(cli_error(msg, usage));
    }

    Ok(a)
}

fn banner(a: &Args) -> String {
    if a.force_emoji {
        format!("🐦 CROWBOOK 📚 {}", VERSION)
    } else {
        format!("CROWBOOK {}", VERSION)
    }
}

fn error_prefix(a: &Args) -> &'static str {
    if a.force_emoji && !a.no_fancy {
        "💣 ERROR"
    } else {
        "ERROR"
    }
}

fn print_banner(a: &Args) {
    if !a.quiet {
        eprintln!("{}", banner(a));
    }
}

fn msg_must_pass_book(a: &Args) -> String {
    format!("{} You must pass the name of a book configuration file.\nFor more information try --help.\n\n", error_prefix(a))
}

fn is_french(a: &Args) -> bool {
    a.lang.as_deref() == Some("fr")
}

fn msg_not_found(a: &Args, path: &str) -> String {
    if is_french(a) {
        format!("{} Impossible de trouver le fichier '{}' pour book", error_prefix(a), path)
    } else {
        format!("{} Could not find file '{}' for book", error_prefix(a), path)
    }
}

fn msg_not_found_chapter(a: &Args, path: &str) -> String {
    if is_french(a) {
        format!("{} {}: Impossible de trouver le fichier '{}' pour book chapter", error_prefix(a), path, path)
    } else {
        format!("{} {}: Could not find file '{}' for book chapter", error_prefix(a), path, path)
    }
}

fn do_help() -> ExitCode {
    print!("{}", HELP_TEXT);
    let _ = io::stdout().flush();
    ExitCode::from(0)
}

fn do_version() -> ExitCode {
    println!("crowbook {}", VERSION);
    ExitCode::from(0)
}

fn do_list_options(a: &Args) -> ExitCode {
    print_banner(a);
    print!("{}", LIST_OPTIONS);
    let _ = io::stdout().flush();
    ExitCode::from(0)
}

fn do_print_template(a: &Args, name: &str) -> ExitCode {
    print_banner(a);
    match get_template(name) {
        Some(content) => {
            print!("{}", content);
            let _ = io::stdout().flush();
            ExitCode::from(0)
        }
        None => {
            eprintln!("{} {} is not a valid template name", error_prefix(a), name);
            ExitCode::from(0)
        }
