fn jaro(s1: &str, s2: &str) -> f64 {
    let a: Vec<char> = s1.chars().collect();
    let b: Vec<char> = s2.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    if a == b { return 1.0; }
    let n = a.len();
    let m = b.len();
    let max_len = n.max(m);
    let match_distance = if max_len / 2 == 0 { 0 } else { max_len / 2 - 1 };
    let mut a_match = vec![false; n];
    let mut b_match = vec![false; m];
    let mut matches = 0usize;
    for i in 0..n {
        let start = if i > match_distance { i - match_distance } else { 0 };
        let end = (i + match_distance + 1).min(m);
        for j in start..end {
            if b_match[j] { continue; }
            if a[i] != b[j] { continue; }
            a_match[i] = true;
            b_match[j] = true;
            matches += 1;
            break;
        }
    }
    if matches == 0 { return 0.0; }
    let mut k = 0usize;
    let mut trans = 0usize;
    for i in 0..n {
        if !a_match[i] { continue; }
        while !b_match[k] { k += 1; }
        if a[i] != b[k] { trans += 1; }
        k += 1;
    }
    let trans = trans as f64 / 2.0;
    let matches_f = matches as f64;
    (matches_f / n as f64 + matches_f / m as f64 + (matches_f - trans) / matches_f) / 3.0
}

fn find_similar_long(arg_name: &str) -> Option<&'static LongOpt> {
    let threshold = 0.7;
    let mut best: Option<&LongOpt> = None;
    let mut best_sim = threshold;
    for opt in known_long_opts() {
        let sim = jaro(&arg_name.to_lowercase(), &opt.name.to_lowercase());
        if sim >= best_sim {
            best_sim = sim;
            best = Some(opt);
        }
    }
    best
}

#[derive(Default, Clone)]
struct Args {
    force_emoji: bool,
    single: bool,
    no_fancy: bool,
    verbose: bool,
    autograph: bool,
    quiet: bool,
    create: Option<Vec<String>>,
    output: Option<String>,
    to: Option<String>,
    set: Option<Vec<String>>,
    list_options: bool,
    lang: Option<String>,
    print_template: Option<String>,
    stats: bool,
    help: bool,
    version: bool,
    book: Option<String>,
}

fn cli_error(msg: &str, usage: &str) -> ExitCode {
    let mut out = String::new();
    out.push_str(&format!("error: {}\n\n", msg));
    if !usage.is_empty() {
        out.push_str(&format!("{}\n\n", usage));
    }
    out.push_str("For more information, try '--help'.\n");
    eprint!("{}", out);
    ExitCode::from(2)
}

fn default_usage() -> &'static str {
    "Usage: executable [OPTIONS] [BOOK]"
}

fn unknown_arg(arg: &str) -> ExitCode {
    // Only try suggestions for long options (starting with --)
    let bare = if let Some(rest) = arg.strip_prefix("--") {
        let name = rest.split('=').next().unwrap_or(rest);
        Some(name)
    } else {
        None
    };
    let similar = bare.and_then(|n| find_similar_long(n));
    let mut msg = format!("unexpected argument '{}' found", arg);
    let usage = if let Some(s) = similar {
        msg.push_str(&format!("\n\n  tip: a similar argument exists: '--{}'", s.name));
        format!("Usage: executable {} [BOOK]", s.usage)
    } else {
        msg.push_str(&format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg));
        default_usage().to_string()
    };
    cli_error(&msg, &usage)
}

fn take_value_for(flag_usage: &str, i: &mut usize, argv: &[String], val_opt: Option<String>) -> Result<String, ExitCode> {
    if let Some(v) = val_opt { return Ok(v); }
    if *i < argv.len() {
        let v = argv[*i].clone();
        *i += 1;
        return Ok(v);
    }
    Err(cli_error(
        &format!("a value is required for '{}' but none was supplied", flag_usage),
        ""))
}

fn parse_args(argv: Vec<String>) -> Result<Args, ExitCode> {
    let mut a = Args::default();
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 1usize;
    let mut after_ddash = false;
    let valid_to = ["epub", "pdf", "html", "tex", "odt", "html.dir"];

    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if after_ddash {
            positionals.push(arg);
            continue;
        }
        if arg == "--" {
            after_ddash = true;
            continue;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, val_opt) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(rest[pos+1..].to_string())),
                None => (rest, None),
            };
            match name {
                "" => {
                    // "--" handled above; "--=" weird case
                    return Err(unknown_arg(&arg));
                }
                "help" => { a.help = true; }
                "version" => { a.version = true; }
                "force-emoji" => { a.force_emoji = true; }
                "single" => { a.single = true; }
                "no-fancy" => { a.no_fancy = true; }
                "verbose" => { a.verbose = true; }
                "autograph" => { a.autograph = true; }
                "quiet" => { a.quiet = true; }
                "list-options" => { a.list_options = true; }
                "stats" => { a.stats = true; }
                "lang" => {
                    a.lang = Some(take_value_for("--lang <lang>", &mut i, &argv, val_opt)?);
                }
                "output" => {
                    a.output = Some(take_value_for("--output <output>", &mut i, &argv, val_opt)?);
                }
                "to" => {
                    let v = match val_opt {
                        Some(v) => v,
                        None => {
                            if i < argv.len() {
                                let v = argv[i].clone();
                                i += 1;
                                v
                            } else {
                                eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                                return Err(ExitCode::from(2));
                            }
                        }
                    };
                    if !valid_to.contains(&v.as_str()) {
                        eprint!("error: invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n", v);
                        return Err(ExitCode::from(2));
                    }
                    a.to = Some(v);
                }
                "print-template" => {
                    a.print_template = Some(take_value_for("--print-template <print-template>", &mut i, &argv, val_opt)?);
                }
                "create" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--create <files>...' but none was supplied",
                            ""));
                    }
                    a.create = Some(vals);
                }
                "set" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--set <set> <set>...' but none was supplied",
                            ""));
                    }
                    a.set = Some(vals);
                }
                _ => {
                    return Err(unknown_arg(&arg));
                }
            }
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0usize;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                let take_short_value = |j: &mut usize, i: &mut usize, argv: &[String], flag: &str| -> Result<String, ExitCode> {
                    // skip optional '='
                    if *j < chars.len() && chars[*j] == '=' { *j += 1; }
                    if *j < chars.len() {
                        let v = chars[*j..].iter().collect::<String>();
                        *j = chars.len();
                        Ok(v)
                    } else if *i < argv.len() {
                        let v = argv[*i].clone();
                        *i += 1;
                        Ok(v)
                    } else {
                        Err(cli_error(&format!("a value is required for '{}' but none was supplied", flag), ""))
                    }
                };
                match c {
                    'h' => a.help = true,
                    'V' => a.version = true,
                    'f' => a.force_emoji = true,
                    's' => a.single = true,
                    'n' => a.no_fancy = true,
                    'v' => a.verbose = true,
                    'a' => a.autograph = true,
                    'q' => a.quiet = true,
                    'l' => a.list_options = true,
                    'S' => a.stats = true,
                    'L' => {
                        a.lang = Some(take_short_value(&mut j, &mut i, &argv, "--lang <lang>")?);
                    }
                    'o' => {
                        a.output = Some(take_short_value(&mut j, &mut i, &argv, "--output <output>")?);
                    }
                    't' => {
                        let v = if j < chars.len() && chars[j] == '=' {
                            j += 1;
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            v
                        } else if j < chars.len() {
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            v
                        } else if i < argv.len() {
                            let v = argv[i].clone();
                            i += 1;
                            v
                        } else {
                            eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                            return Err(ExitCode::from(2));
                        };
                        if !valid_to.contains(&v.as_str()) {
                            eprint!("error: invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n", v);
                            return Err(ExitCode::from(2));
                        }
                        a.to = Some(v);
                    }
                    'c' => {
                        let mut vals: Vec<String> = Vec::new();
                        if j < chars.len() && chars[j] == '=' { j += 1; }
                        if j < chars.len() {
                            vals.push(chars[j..].iter().collect::<String>());
                            j = chars.len();
                        }
                        while i < argv.len() && !argv[i].starts_with('-') {
                            vals.push(argv[i].clone());
                            i += 1;
                        }
                        if vals.is_empty() {
                            return Err(cli_error(
                                "a value is required for '--create <files>...' but none was supplied",
                                ""));
                        }
                        a.create = Some(vals);
                    }
                    _ => {
                        let bad = format!("-{}", c);
                        return Err(unknown_arg(&bad));
                    }
                }
            }
            continue;
        }
        positionals.push(arg);
    }

    if positionals.len() > 1 {
        return Err(unknown_arg(&positionals[1]));
    }
    if let Some(p) = positionals.into_iter().next() {
        a.book = Some(p);
    }

    if a.output.is_some() && a.to.is_none() {
        let msg = "the following required arguments were not provided:\n  --to <to>";
        let usage = if a.create.is_some() {
            "Usage: executable --to <to> --create <files>... --output <output> [BOOK]"
        } else {
            "Usage: executable --to <to> --output <output> [BOOK]"
        };
        return Err(cli_error(msg, usage));
    }

    Ok(a)
}

fn banner(a: &Args) -> String {
    if a.force_emoji {
        format!("🐦 CROWBOOK 📚 {}", VERSION)
    } else {
        format!("CROWBOOK {}", VERSION)
    }
}

fn error_prefix(a: &Args) -> &'static str {
    if a.force_emoji && !a.no_fancy {
        "💣 ERROR"
    } else {
        "ERROR"
    }
}

fn print_banner(a: &Args) {
    if !a.quiet {
        eprintln!("{}", banner(a));
    }
}

fn msg_must_pass_book(a: &Args) -> String {
    format!("{} You must pass the name of a book configuration file.\nFor more information try --help.\n\n", error_prefix(a))
}

fn is_french(a: &Args) -> bool {
    a.lang.as_deref() == Some("fr")
}

fn msg_not_found(a: &Args, path: &str) -> String {
    if is_french(a) {
        format!("{} Impossible de trouver le fichier '{}' pour book", error_prefix(a), path)
    } else {
        format!("{} Could not find file '{}' for book", error_prefix(a), path)
    }
}

fn msg_not_found_chapter(a: &Args, path: &str) -> String {
    if is_french(a) {
        format!("{} {}: Impossible de trouver le fichier '{}' pour book chapter", error_prefix(a), path, path)
    } else {
        format!("{} {}: Could not find file '{}' for book chapter", error_prefix(a), path, path)
    }
}

fn do_help() -> ExitCode {
    print!("{}", HELP_TEXT);
    let _ = io::stdout().flush();
    ExitCode::from(0)
}

fn do_version() -> ExitCode {
    println!("crowbook {}", VERSION);
    ExitCode::from(0)
}

fn do_list_options(a: &Args) -> ExitCode {
    print_banner(a);
    print!("{}", LIST_OPTIONS);
    let _ = io::stdout().flush();
    ExitCode::from(0)
}

fn do_print_template(a: &Args, name: &str) -> ExitCode {
    print_banner(a);
    match get_template(name) {
        Some(content) => {
            print!("{}", content);
            let _ = io::stdout().flush();
            ExitCode::from(0)
        }
        None => {
            eprintln!("{} {} is not a valid template name", error_prefix(a), name);
            ExitCode::from(0)
        }
    }
}

fn scaffold_content(files: &[String]) -> String {
    let mut s = String::new();
    s.push_str("\"author: Your name\"\n");
    s.push_str("\"title: Your title\"\n");
    s.push_str("\"lang: en\"\n");
    s.push('\n');
    s.push_str("\"## Output formats\"\n");
    s.push('\n');
    s.push_str("\"# Uncomment and fill to generate files\"\n");
    s.push_str("\"# output.html: some_file.html\"\n");
    s.push_str("\"# output.epub: some_file.epub\"\n");
    s.push_str("\"# output.pdf: some_file.pdf\"\n");
    s.push('\n');
    s.push_str("\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"\n");
    s.push_str("\"# output: [pdf, epub, html]\"\n");
    s.push('\n');
    s.push_str("\"# Uncomment and fill to set cover image (for EPUB)\"\n");
    s.push_str("\"# cover: some_cover.png\"\n");
    s.push('\n');
    s.push_str("## List of chapters\n");
    for f in files {
        s.push_str(&format!("+ {}\n", f));
    }
    s
}

fn do_create(a: &Args, files: &[String]) -> ExitCode {
    print_banner(a);
    if let Some(book_path) = &a.book {
        if Path::new(book_path).exists() {
            eprintln!("{} Could not create file {}: it already exists!", error_prefix(a), book_path);
            return ExitCode::from(0);
        }
        let content = scaffold_content(files);
        match fs::write(book_path, content) {
            Ok(_) => {
                println!("Created {}, now you'll have to complete it!", book_path);
                ExitCode::from(0)
            }
            Err(e) => {
                eprintln!("{} Could not create file {}: {}", error_prefix(a), book_path, e);
                ExitCode::from(0)
            }
        }
    } else {
        print!("{}", scaffold_content(files));
        let _ = io::stdout().flush();
        ExitCode::from(0)
    }
}

struct Book {
    chapters: Vec<String>,
}

fn parse_book_file(path: &str, a: &Args) -> Result<Book, String> {
    let content = fs::read_to_string(path).map_err(|e| e.to_string())?;
    let mut book = Book { chapters: Vec::new() };
    let mut lineno = 0usize;
    for line in content.lines() {
        lineno += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("+ ")
            .or_else(|| trimmed.strip_prefix("- "))
            .or_else(|| trimmed.strip_prefix("! ")) {
            let chap_path = rest.trim().to_string();
            let chap_full = if Path::new(&chap_path).is_absolute() {
                chap_path.clone()
            } else {
                let base = Path::new(path).parent().unwrap_or(Path::new("."));
                base.join(&chap_path).to_string_lossy().to_string()
            };
            if !Path::new(&chap_full).exists() {
                let msg = if is_french(a) {
                    format!("{}:{}: Impossible de trouver le fichier '{}' pour book chapter", path, lineno, chap_path)
                } else {
                    format!("{}:{}: Could not find file '{}' for book chapter", path, lineno, chap_path)
                };
                return Err(msg);
            }
            book.chapters.push(chap_full);
            continue;
        }
        if trimmed.contains(':') {
            continue;
        }
        let msg = if is_french(a) {
            format!("{}:{}: Erreur dans l'analyse du fichier de configuration : \"impossible d'analyser %{{file}} comme un fichier de livre.\"\nVous voulez peut-être lancer crowbook avec l'argument --single ?\n", path, lineno)
        } else {
            format!("{}:{}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"\nMaybe you meant to run crowbook with the --single argument?\n", path, lineno)
        };
        return Err(msg);
    }
    Ok(book)
}

fn count_stats(file: &str) -> (usize, usize) {
    let content = fs::read_to_string(file).unwrap_or_default();
    let mut text = String::new();
    for line in content.lines() {
        let t = line.trim();
        let t = t.trim_start_matches(|c: char| c == '#').trim_start();
        let t = t.trim_start_matches(|c: char| c == '*' || c == '-' || c == '+').trim_start();
        if !text.is_empty() && !t.is_empty() {
            text.push(' ');
        }
        text.push_str(t);
    }
    let chars = text.chars().count();
    let words = text.split_whitespace().count();
    (chars, words)
}

fn do_stats(_a: &Args, book: &Book) -> ExitCode {
    let mut rows: Vec<(String, usize, usize)> = Vec::new();
    let mut tchars = 0usize;
    let mut twords = 0usize;
    for ch in &book.chapters {
        let (c, w) = count_stats(ch);
        rows.push((ch.clone(), c, w));
        tchars += c;
        twords += w;
    }
    let max_name: usize = rows.iter().map(|r| r.0.chars().count()).max().unwrap_or(0);
    let name_w = max_name.max(6) + 7; // "TOTAL:" = 6
    println!("{:<width$}{:>5}{:>11}{:>12}", "Chapter", "Chars", "Words", "Chars/Word", width = name_w);
    println!("---------");
    for (n, c, w) in &rows {
        let cw = if *w > 0 { (*c as f64) / (*w as f64) } else { 0.0 };
        println!("{:<width$}{:>5}{:>11}{:>12.2}", n, c, w, cw, width = name_w);
    }
    println!("---------");
    let tcw = if twords > 0 { (tchars as f64) / (twords as f64) } else { 0.0 };
    println!("{:<width$}{:>5}{:>11}{:>12.2}\n", "TOTAL:", tchars, twords, tcw, width = name_w);
    ExitCode::from(0)
}

fn do_book(a: &Args) -> ExitCode {
    print_banner(a);
    let book_path = a.book.as_deref();
    if a.single {
        let path = match book_path {
            Some(p) => p,
            None => {
                eprint!("{}", msg_must_pass_book(a));
                return ExitCode::from(0);
            }
        };
        if !Path::new(path).exists() && path != "-" {
            eprintln!("{}", msg_not_found_chapter(a, path));
            return ExitCode::from(0);
        }
        return ExitCode::from(0);
    }
    let path = match book_path {
        Some(p) => p,
        None => {
            eprint!("{}", msg_must_pass_book(a));
            return ExitCode::from(0);
        }
    };
    if path != "-" && !Path::new(path).exists() {
        eprintln!("{}", msg_not_found(a, path));
        return ExitCode::from(0);
    }
    let book = if path == "-" {
        let mut s = String::new();
        let _ = io::stdin().read_to_string(&mut s);
        Book { chapters: Vec::new() }
    } else {
        match parse_book_file(path, a) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("{} {}", error_prefix(a), e);
                return ExitCode::from(0);
            }
        }
    };

    // Handle --set if any: emit errors for unknown keys
    if let Some(set_vals) = &a.set {
        // Pair off key value
        let mut pairs = set_vals.chunks(2);
        let known_keys = &[
            "author","title","lang","subject","description","cover","subtitle",
            "license","version","date","autograph",
        ];
        while let Some(pair) = pairs.next() {
            if pair.len() < 2 { break; }
            let k = &pair[0];
            let _v = &pair[1];
            if !known_keys.iter().any(|x| x == k) && !k.contains('.') {
                eprintln!("{} Error in setting key {}: {}:1: Error converting BookOption: unrecognized key '{}'",
                          error_prefix(a), k, path, k);
                return ExitCode::from(0);
            }
        }
    }

    if a.stats {
        return do_stats(a, &book);
    }
    ExitCode::from(0)
}

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let args = match parse_args(argv) {
        Ok(a) => a,
        Err(code) => return code,
    };

    if args.help {
        return do_help();
    }
    if args.version {
        return do_version();
    }
    if args.list_options {
        return do_list_options(&args);
    }
    if let Some(t) = &args.print_template {
        return do_print_template(&args, t);
    }
    if let Some(files) = args.create.clone() {
        return do_create(&args, &files);
    }
    do_book(&args)
}
