        "html.standalone.template" => Some(T_HTML_STANDALONE_TEMPLATE),
        "html.standalone.js" => Some(T_HTML_STANDALONE_JS),
        "html.dir.template" => Some(T_HTML_DIR_TEMPLATE),
        "epub.css" => Some(T_EPUB_CSS),
        "epub.chapter.xhtml" => Some(T_EPUB_CHAPTER_XHTML),
        "epub.titlepage.xhtml" => Some(T_EPUB_TITLEPAGE_XHTML),
        "tex.template" => Some(T_TEX_TEMPLATE),
        _ => None,
    }
}

// Known long options and their usage suffixes
// The list is kept sorted alphabetically by long name.
struct LongOpt {
    name: &'static str,
    usage: &'static str,
}

fn known_long_opts() -> &'static [LongOpt] {
    // Alphabetical order by `name`
    &[
        LongOpt { name: "autograph",      usage: "--autograph" },
        LongOpt { name: "create",         usage: "--create <files>..." },
        LongOpt { name: "force-emoji",    usage: "--force-emoji" },
        LongOpt { name: "help",           usage: "--help" },
        LongOpt { name: "lang",           usage: "--lang <lang>" },
        LongOpt { name: "list-options",   usage: "--list-options" },
        LongOpt { name: "no-fancy",       usage: "--no-fancy" },
        LongOpt { name: "output",         usage: "--output <output>" },
        LongOpt { name: "print-template", usage: "--print-template <print-template>" },
        LongOpt { name: "quiet",          usage: "--quiet" },
        LongOpt { name: "set",            usage: "--set <set> <set>..." },
        LongOpt { name: "single",         usage: "--single" },
        LongOpt { name: "stats",          usage: "--stats" },
        LongOpt { name: "to",             usage: "--to <to>" },
        LongOpt { name: "verbose",        usage: "--verbose" },
        LongOpt { name: "version",        usage: "--version" },
    ]
}

fn jaro(s1: &str, s2: &str) -> f64 {
    let a: Vec<char> = s1.chars().collect();
    let b: Vec<char> = s2.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    if a == b { return 1.0; }
    let n = a.len();
    let m = b.len();
    let max_len = n.max(m);
    let match_distance = if max_len / 2 == 0 { 0 } else { max_len / 2 - 1 };
    let mut a_match = vec![false; n];
    let mut b_match = vec![false; m];
    let mut matches = 0usize;
    for i in 0..n {
        let start = if i > match_distance { i - match_distance } else { 0 };
        let end = (i + match_distance + 1).min(m);
        for j in start..end {
            if b_match[j] { continue; }
            if a[i] != b[j] { continue; }
            a_match[i] = true;
            b_match[j] = true;
            matches += 1;
            break;
        }
    }
    if matches == 0 { return 0.0; }
    let mut k = 0usize;
    let mut trans = 0usize;
    for i in 0..n {
        if !a_match[i] { continue; }
        while !b_match[k] { k += 1; }
        if a[i] != b[k] { trans += 1; }
        k += 1;
    }
    let trans = trans as f64 / 2.0;
    let matches_f = matches as f64;
    (matches_f / n as f64 + matches_f / m as f64 + (matches_f - trans) / matches_f) / 3.0
}

fn find_similar_long(arg_name: &str) -> Option<&'static LongOpt> {
    let threshold = 0.7;
    let mut best: Option<&LongOpt> = None;
    let mut best_sim = threshold;
    for opt in known_long_opts() {
        let sim = jaro(&arg_name.to_lowercase(), &opt.name.to_lowercase());
        if sim >= best_sim {
            best_sim = sim;
            best = Some(opt);
        }
    }
    best
}

#[derive(Default, Clone)]
struct Args {
    force_emoji: bool,
    single: bool,
    no_fancy: bool,
    verbose: bool,
    autograph: bool,
    quiet: bool,
    create: Option<Vec<String>>,
    output: Option<String>,
    to: Option<String>,
    set: Option<Vec<String>>,
    list_options: bool,
    lang: Option<String>,
    print_template: Option<String>,
    stats: bool,
    help: bool,
    version: bool,
    book: Option<String>,
}

fn cli_error(msg: &str, usage: &str) -> ExitCode {
    let mut out = String::new();
    out.push_str(&format!("error: {}\n\n", msg));
    if !usage.is_empty() {
        out.push_str(&format!("{}\n\n", usage));
    }
    out.push_str("For more information, try '--help'.\n");
    eprint!("{}", out);
    ExitCode::from(2)
}

fn default_usage() -> &'static str {
    "Usage: executable [OPTIONS] [BOOK]"
}

fn unknown_arg(arg: &str) -> ExitCode {
    // Only try suggestions for long options (starting with --)
    let bare = if let Some(rest) = arg.strip_prefix("--") {
        let name = rest.split('=').next().unwrap_or(rest);
        Some(name)
    } else {
        None
    };
    let similar = bare.and_then(|n| find_similar_long(n));
    let mut msg = format!("unexpected argument '{}' found", arg);
    let usage = if let Some(s) = similar {
        msg.push_str(&format!("\n\n  tip: a similar argument exists: '--{}'", s.name));
        format!("Usage: executable {} [BOOK]", s.usage)
    } else {
        msg.push_str(&format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", arg, arg));
        default_usage().to_string()
    };
    cli_error(&msg, &usage)
}

fn take_value_for(flag_usage: &str, i: &mut usize, argv: &[String], val_opt: Option<String>) -> Result<String, ExitCode> {
    if let Some(v) = val_opt { return Ok(v); }
    if *i < argv.len() {
        let v = argv[*i].clone();
        *i += 1;
        return Ok(v);
    }
    Err(cli_error(
        &format!("a value is required for '{}' but none was supplied", flag_usage),
        ""))
}

fn parse_args(argv: Vec<String>) -> Result<Args, ExitCode> {
    let mut a = Args::default();
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 1usize;
    let mut after_ddash = false;
    let valid_to = ["epub", "pdf", "html", "tex", "odt", "html.dir"];

    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if after_ddash {
            positionals.push(arg);
            continue;
        }
        if arg == "--" {
            after_ddash = true;
            continue;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, val_opt) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(rest[pos+1..].to_string())),
                None => (rest, None),
            };
            match name {
                "" => {
                    // "--" handled above; "--=" weird case
                    return Err(unknown_arg(&arg));
                }
                "help" => { a.help = true; }
                "version" => { a.version = true; }
                "force-emoji" => { a.force_emoji = true; }
                "single" => { a.single = true; }
                "no-fancy" => { a.no_fancy = true; }
                "verbose" => { a.verbose = true; }
                "autograph" => { a.autograph = true; }
                "quiet" => { a.quiet = true; }
                "list-options" => { a.list_options = true; }
                "stats" => { a.stats = true; }
                "lang" => {
                    a.lang = Some(take_value_for("--lang <lang>", &mut i, &argv, val_opt)?);
                }
                "output" => {
                    a.output = Some(take_value_for("--output <output>", &mut i, &argv, val_opt)?);
                }
                "to" => {
                    let v = match val_opt {
                        Some(v) => v,
                        None => {
                            if i < argv.len() {
                                let v = argv[i].clone();
                                i += 1;
                                v
                            } else {
                                eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                                return Err(ExitCode::from(2));
                            }
                        }
                    };
                    if !valid_to.contains(&v.as_str()) {
                        eprint!("error: invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n", v);
                        return Err(ExitCode::from(2));
                    }
                    a.to = Some(v);
                }
                "print-template" => {
                    a.print_template = Some(take_value_for("--print-template <print-template>", &mut i, &argv, val_opt)?);
                }
                "create" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--create <files>...' but none was supplied",
                            ""));
                    }
                    a.create = Some(vals);
                }
                "set" => {
                    let mut vals: Vec<String> = Vec::new();
                    if let Some(v) = val_opt { vals.push(v); }
                    while i < argv.len() && !argv[i].starts_with('-') {
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                    if vals.is_empty() {
                        return Err(cli_error(
                            "a value is required for '--set <set> <set>...' but none was supplied",
                            ""));
                    }
                    a.set = Some(vals);
                }
                _ => {
                    return Err(unknown_arg(&arg));
                }
            }
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0usize;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                let take_short_value = |j: &mut usize, i: &mut usize, argv: &[String], flag: &str| -> Result<String, ExitCode> {
                    // skip optional '='
                    if *j < chars.len() && chars[*j] == '=' { *j += 1; }
                    if *j < chars.len() {
                        let v = chars[*j..].iter().collect::<String>();
                        *j = chars.len();
                        Ok(v)
                    } else if *i < argv.len() {
                        let v = argv[*i].clone();
                        *i += 1;
                        Ok(v)
                    } else {
                        Err(cli_error(&format!("a value is required for '{}' but none was supplied", flag), ""))
                    }
                };
                match c {
                    'h' => a.help = true,
                    'V' => a.version = true,
                    'f' => a.force_emoji = true,
                    's' => a.single = true,
                    'n' => a.no_fancy = true,
                    'v' => a.verbose = true,
                    'a' => a.autograph = true,
                    'q' => a.quiet = true,
                    'l' => a.list_options = true,
                    'S' => a.stats = true,
                    'L' => {
                        a.lang = Some(take_short_value(&mut j, &mut i, &argv, "--lang <lang>")?);
                    }
                    'o' => {
                        a.output = Some(take_short_value(&mut j, &mut i, &argv, "--output <output>")?);
                    }
                    't' => {
                        let v = if j < chars.len() && chars[j] == '=' {
                            j += 1;
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            v
                        } else if j < chars.len() {
                            let v = chars[j..].iter().collect::<String>();
                            j = chars.len();
                            v
                        } else if i < argv.len() {
                            let v = argv[i].clone();
                            i += 1;
                            v
                        } else {
                            eprint!("error: a value is required for '--to <to>' but none was supplied\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n");
                            return Err(ExitCode::from(2));
                        };
                        if !valid_to.contains(&v.as_str()) {
                            eprint!("error: invalid value '{}' for '--to <to>'\n  [possible values: epub, pdf, html, tex, odt, html.dir]\n\nFor more information, try '--help'.\n", v);
                            return Err(ExitCode::from(2));
                        }
                        a.to = Some(v);
                    }
                    'c' => {
                        let mut vals: Vec<String> = Vec::new();
                        if j < chars.len() && chars[j] == '=' { j += 1; }
                        if j < chars.len() {
                            vals.push(chars[j..].iter().collect::<String>());
                            j = chars.len();
                        }
                        while i < argv.len() && !argv[i].starts_with('-') {
                            vals.push(argv[i].clone());
                            i += 1;
                        }
                        if vals.is_empty() {
                            return Err(cli_error(
                                "a value is required for '--create <files>...' but none was supplied",
                                ""));
                        }
                        a.create = Some(vals);
                    }
                    _ => {
                        let bad = format!("-{}", c);
                        return Err(unknown_arg(&bad));
                    }
                }
            }
            continue;
        }
        positionals.push(arg);
    }

    if positionals.len() > 1 {
        return Err(unknown_arg(&positionals[1]));
    }
    if let Some(p) = positionals.into_iter().next() {
        a.book = Some(p);
    }

    if a.output.is_some() && a.to.is_none() {
        let msg = "the following required arguments were not provided:\n  --to <to>";
        let usage = if a.create.is_some() {
            "Usage: executable --to <to> --create <files>... --output <output> [BOOK]"
        } else {
            "Usage: executable --to <to> --output <output> [BOOK]"
        };
        return Err(cli_error(msg, usage));
    }

    Ok(a)
}

fn banner(a: &Args) -> String {
    if a.force_emoji {
        format!("🐦 CROWBOOK 📚 {}", VERSION)
    } else {
        format!("CROWBOOK {}", VERSION)
    }
}

fn error_prefix(a: &Args) -> &'static str {
    if a.force_emoji && !a.no_fancy {
        "💣 ERROR"
    } else {
        "ERROR"
    }
}

fn print_banner(a: &Args) {
    if !a.quiet {
        eprintln!("{}", banner(a));
    }
}

fn msg_must_pass_book(a: &Args) -> String {
    format!("{} You must pass the name of a book configuration file.\nFor more information try --help.\n\n", error_prefix(a))
}

fn is_french(a: &Args) -> bool {
    a.lang.as_deref() == Some("fr")
}

fn msg_not_found(a: &Args, path: &str) -> String {
    if is_french(a) {
        format!("{} Impossible de trouver le fichier '{}' pour book", error_prefix(a), path)
    } else {
        format!("{} Could not find file '{}' for book", error_prefix(a), path)
    }
}

fn msg_not_found_chapter(a: &Args, path: &str) -> String {
    if is_french(a) {
        format!("{} {}: Impossible de trouver le fichier '{}' pour book chapter", error_prefix(a), path, path)
    } else {
        format!("{} {}: Could not find file '{}' for book chapter", error_prefix(a), path, path)
    }
}

