fn scaffold_content(files: &[String]) -> String {
    let mut s = String::new();
    s.push_str("\"author: Your name\"\n");
    s.push_str("\"title: Your title\"\n");
    s.push_str("\"lang: en\"\n");
    s.push('\n');
    s.push_str("\"## Output formats\"\n");
    s.push('\n');
    s.push_str("\"# Uncomment and fill to generate files\"\n");
    s.push_str("\"# output.html: some_file.html\"\n");
    s.push_str("\"# output.epub: some_file.epub\"\n");
    s.push_str("\"# output.pdf: some_file.pdf\"\n");
    s.push('\n');
    s.push_str("\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"\n");
    s.push_str("\"# output: [pdf, epub, html]\"\n");
    s.push('\n');
    s.push_str("\"# Uncomment and fill to set cover image (for EPUB)\"\n");
    s.push_str("\"# cover: some_cover.png\"\n");
    s.push('\n');
    s.push_str("## List of chapters\n");
    for f in files {
        s.push_str(&format!("+ {}\n", f));
    }
    s
}

fn do_create(a: &Args, files: &[String]) -> ExitCode {
    print_banner(a);
    if let Some(book_path) = &a.book {
        if Path::new(book_path).exists() {
            eprintln!("{} Could not create file {}: it already exists!", error_prefix(a), book_path);
            return ExitCode::from(0);
        }
        let content = scaffold_content(files);
        match fs::write(book_path, content) {
            Ok(_) => {
                println!("Created {}, now you'll have to complete it!", book_path);
                ExitCode::from(0)
            }
            Err(e) => {
                eprintln!("{} Could not create file {}: {}", error_prefix(a), book_path, e);
                ExitCode::from(0)
            }
        }
    } else {
        print!("{}", scaffold_content(files));
        let _ = io::stdout().flush();
        ExitCode::from(0)
    }
}

struct Book {
    chapters: Vec<String>,
}

fn parse_book_file(path: &str, a: &Args) -> Result<Book, String> {
    let content = fs::read_to_string(path).map_err(|e| e.to_string())?;
    let mut book = Book { chapters: Vec::new() };
    let mut lineno = 0usize;
    for line in content.lines() {
        lineno += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("+ ")
            .or_else(|| trimmed.strip_prefix("- "))
            .or_else(|| trimmed.strip_prefix("! ")) {
            let chap_path = rest.trim().to_string();
            let chap_full = if Path::new(&chap_path).is_absolute() {
                chap_path.clone()
            } else {
                let base = Path::new(path).parent().unwrap_or(Path::new("."));
                base.join(&chap_path).to_string_lossy().to_string()
            };
            if !Path::new(&chap_full).exists() {
                let msg = if is_french(a) {
                    format!("{}:{}: Impossible de trouver le fichier '{}' pour book chapter", path, lineno, chap_path)
                } else {
                    format!("{}:{}: Could not find file '{}' for book chapter", path, lineno, chap_path)
                };
                return Err(msg);
            }
            book.chapters.push(chap_full);
            continue;
        }
        if trimmed.contains(':') {
            continue;
        }
        let msg = if is_french(a) {
            format!("{}:{}: Erreur dans l'analyse du fichier de configuration : \"impossible d'analyser %{{file}} comme un fichier de livre.\"\nVous voulez peut-être lancer crowbook avec l'argument --single ?\n", path, lineno)
        } else {
            format!("{}:{}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"\nMaybe you meant to run crowbook with the --single argument?\n", path, lineno)
        };
        return Err(msg);
    }
    Ok(book)
}

fn count_stats(file: &str) -> (usize, usize) {
    let content = fs::read_to_string(file).unwrap_or_default();
    let mut text = String::new();
    for line in content.lines() {
        let t = line.trim();
        let t = t.trim_start_matches(|c: char| c == '#').trim_start();
        let t = t.trim_start_matches(|c: char| c == '*' || c == '-' || c == '+').trim_start();
        if !text.is_empty() && !t.is_empty() {
            text.push(' ');
        }
        text.push_str(t);
    }
    let chars = text.chars().count();
    let words = text.split_whitespace().count();
    (chars, words)
}

fn do_stats(_a: &Args, book: &Book) -> ExitCode {
    let mut rows: Vec<(String, usize, usize)> = Vec::new();
    let mut tchars = 0usize;
    let mut twords = 0usize;
    for ch in &book.chapters {
        let (c, w) = count_stats(ch);
        rows.push((ch.clone(), c, w));
        tchars += c;
        twords += w;
    }
    let max_name: usize = rows.iter().map(|r| r.0.chars().count()).max().unwrap_or(0);
    let name_w = max_name.max(6) + 7; // "TOTAL:" = 6
    println!("{:<width$}{:>5}{:>11}{:>12}", "Chapter", "Chars", "Words", "Chars/Word", width = name_w);
    println!("---------");
    for (n, c, w) in &rows {
        let cw = if *w > 0 { (*c as f64) / (*w as f64) } else { 0.0 };
        println!("{:<width$}{:>5}{:>11}{:>12.2}", n, c, w, cw, width = name_w);
    }
    println!("---------");
    let tcw = if twords > 0 { (tchars as f64) / (twords as f64) } else { 0.0 };
    println!("{:<width$}{:>5}{:>11}{:>12.2}\n", "TOTAL:", tchars, twords, tcw, width = name_w);
    ExitCode::from(0)
}

fn do_book(a: &Args) -> ExitCode {
    print_banner(a);
    let book_path = a.book.as_deref();
    if a.single {
        let path = match book_path {
            Some(p) => p,
            None => {
                eprint!("{}", msg_must_pass_book(a));
                return ExitCode::from(0);
            }
        };
        if !Path::new(path).exists() && path != "-" {
            eprintln!("{}", msg_not_found_chapter(a, path));
            return ExitCode::from(0);
        }
        return ExitCode::from(0);
    }
    let path = match book_path {
        Some(p) => p,
        None => {
            eprint!("{}", msg_must_pass_book(a));
            return ExitCode::from(0);
        }
    };
    if path != "-" && !Path::new(path).exists() {
        eprintln!("{}", msg_not_found(a, path));
        return ExitCode::from(0);
    }
    let book = if path == "-" {
        let mut s = String::new();
        let _ = io::stdin().read_to_string(&mut s);
        Book { chapters: Vec::new() }
    } else {
        match parse_book_file(path, a) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("{} {}", error_prefix(a), e);
                return ExitCode::from(0);
            }
        }
    };

    // Handle --set if any: emit errors for unknown keys
    if let Some(set_vals) = &a.set {
        // Pair off key value
        let mut pairs = set_vals.chunks(2);
        let known_keys = &[
            "author","title","lang","subject","description","cover","subtitle",
            "license","version","date","autograph",
        ];
        while let Some(pair) = pairs.next() {
            if pair.len() < 2 { break; }
            let k = &pair[0];
            let _v = &pair[1];
            if !known_keys.iter().any(|x| x == k) && !k.contains('.') {
                eprintln!("{} Error in setting key {}: {}:1: Error converting BookOption: unrecognized key '{}'",
                          error_prefix(a), k, path, k);
